string contextBeforeFuse=Coordination.Configuration(c);var fuseRating=new SwitchgearRating{Manufacturer="QA",Reference="FUSE25",Family=SwitchgearFamily.gG,VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,RatedA=25,BreakingKA=50,I2A=40,Source="QA fuse",DataVersion="2026.10",Standard="QA",Sheet="QA"};c.SwitchgearSelection=SwitchgearSelection.Candidate(c,fuseRating,SwitchgearFamily.gG,PoleLayout.ThreePole,false);Check(Coordination.Configuration(c)!=contextBeforeFuse,"additional physical device changes pair association context");var fuseCurve=Curve(ResponseKind.PeakKA);fuseCurve.Reference="FUSE25";fuseCurve.MagneticPickupA=null;ProtectionResponses.Attach(p,c,fuseCurve);Check(ProtectionResponses.Matches(p,c,c.ProtectionResponses.Peak),"selected fuse may have its own peak curve");Check(c.Protection.MagneticTripA==125,"fuse curve does not overwrite primary magnetic setting");c.SwitchgearSelection=null;Check(!ProtectionResponses.Matches(p,c,c.ProtectionResponses.Peak),"removed fuse cannot retain nominal curve binding");ProtectionResponses.Attach(p,c,Curve(ResponseKind.PeakKA));Check(Coordination.Configuration(c)==contextBeforeFuse,"restoring exact prior device curve configuration reproduces context");
