string active=Path.Combine(dir,"active.csv");ProtectionResponses.Export(Curve(ResponseKind.TimeSeconds),active);ProtectionResponses.Export(Curve(ResponseKind.TimeSeconds),active);var before=File.ReadAllBytes(active);var backup=File.ReadAllBytes(active+".bak");Reject(delegate{ProtectionResponses.Export(invalid,active);},"invalid export rejected");Check(File.ReadAllBytes(active).SequenceEqual(before)&&File.ReadAllBytes(active+".bak").SequenceEqual(backup),"invalid export preserves destination and backup");string text=File.ReadAllText(active);string mixed=Path.Combine(dir,"mixed.csv");var lines=text.Replace("\r","").Split('\n');lines[2]=lines[2].Replace("BR25","DIFFERENT");File.WriteAllText(mixed,String.Join("\n",lines));Reject(delegate{ProtectionResponses.Import(mixed);},"mixed metadata/settings across points rejected");ProtectionResponses.Export(null,Path.Combine(dir,"template.csv"));Check(File.ReadAllText(Path.Combine(dir,"template.csv")).TrimStart('\uFEFF').Trim()==ProtectionResponses.Header,"empty template has explicit schema");Reject(delegate{ProtectionResponses.Import(Path.Combine(dir,"template.csv"));},"template without points is not a usable curve");string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32L*1024*1024+1);Reject(delegate{ProtectionResponses.Import(large);},"oversized import rejected");var huge=Curve(ResponseKind.TimeSeconds);huge.Source=huge.Settings=huge.Conditions=new string('x',2000);huge.Points.Clear();for(int i=1;i<=6000;i++)huge.Points.Add(new ResponsePoint{CurrentA=i,Lower=1,Upper=2});Reject(delegate{ProtectionResponses.Export(huge,active);},"oversized export rejected");Check(File.ReadAllBytes(active).SequenceEqual(before)&&File.ReadAllBytes(active+".bak").SequenceEqual(backup)&&Directory.GetFiles(dir,"*.tmp").Length==0,"size overflow preserves files and cleans temp");
string fileProject=Path.Combine(dir,"project.circuito");p.Save(fileProject);string saved=File.ReadAllText(fileProject);Check(saved.Contains("protection-responses-v1")&&saved.Contains("\"FileVersion\":4"),"new response capability guards persistence");var loaded=Project.Load(fileProject);Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)),"full report and curves reproduce after reopen");Near(loaded.Boards[0].Circuits[0].ProtectionResponses.Energy.Curve.At(midpoint).Upper,1440,"reopened energy response reference");var copy=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(copy.ProtectionResponses!=c.ProtectionResponses&&copy.ProtectionResponses.Time.Curve.Points[0]!=c.ProtectionResponses.Time.Curve.Points[0],"duplicated response points independent");p.Boards[0].Circuits.Remove(copy);File.WriteAllText(fileProject,saved.Replace(ProtectionResponses.EngineId,"future-responses-engine"));Reject(delegate{Project.Load(fileProject);},"unknown response engine rejected");File.WriteAllText(fileProject,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{fileProject});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual prior executable rejects response capability");}
p.Save(Path.Combine(artifacts,"origem.circuito"));using(var w=new StreamWriter(Path.Combine(artifacts,"consulta.csv"))){w.WriteLine("Kind;CurrentA;Lower;Upper;Unit");foreach(ResponseKind kind in Enum.GetValues(typeof(ResponseKind))){var pt=c.ProtectionResponses.For(kind).Curve.At(midpoint);w.WriteLine(kind+";"+midpoint.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+";"+pt.Lower.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+";"+pt.Upper.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+";"+ProtectionResponses.Unit(kind));}}File.WriteAllText(Path.Combine(artifacts,"memoria.txt"),EngineeringReport.Memory(p,Engineering.Analyze(p)),new UTF8Encoding(true));using(var form=new ProtectionResponsesForm(p,c)){form.CreateControl();Check(!form.Changed,"opening response chart does not modify project");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();var picker=(ComboBox)typeof(ProtectionResponsesForm).GetField("kind",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);for(int i=0;i<3;i++){picker.SelectedIndex=i;Application.DoEvents();form.Refresh();picker.Refresh();form.Update();Application.DoEvents();Check(picker.Text==picker.Items[i].ToString(),"response type selector displays selected units");using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"curva-"+i+".png"));}}form.Hide();}}
Console.WriteLine("PASS: "+n+" protection-response assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
